"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[58739],{19024:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates a new `GenericPoolInstance` pool.\\n\\nThe `objectTemplate` is cloned immediately; the original is never\\nre-parented.  If `initialSize > 0` the pool is pre-filled with clones\\nand the optional `insertFunction` is called on each one.","params":[{"name":"objectTemplate","desc":"Template to clone. Must have `Archivable = true`. Defaults to a blank `Part`.","lua_type":"PVInstance?"},{"name":"initialSize","desc":"Number of instances to pre-allocate. Defaults to `0`.","lua_type":"number?"},{"name":"maxSize","desc":"Hard cap on pool size (`-1` = unlimited). Defaults to `-1`.","lua_type":"number?"},{"name":"expandSize","desc":"How many clones to create when the pool is exhausted. Defaults to `50`.","lua_type":"number?"},{"name":"location","desc":"Parent for the internal storage `Folder`. Defaults to `workspace`.","lua_type":"Instance?"},{"name":"insertFunction","desc":"Optional callback invoked each time a new clone is created.","lua_type":"((PVInstance) -> ())?"}],"returns":[{"desc":"","lua_type":"GenericPoolInstance"}],"function_type":"static","tags":["constructor"],"source":{"line":208,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"SetMaxSize","desc":"Sets the maximum pool size.  If the pool currently holds more instances\\nthan the new cap, the excess are destroyed immediately.  Pass `-1` for\\nunlimited.","params":[{"name":"maxSize","desc":"New cap. `-1` = unlimited.","lua_type":"number?"}],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolInstance"}],"function_type":"method","source":{"line":282,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"SetLocation","desc":"Moves the pool\'s internal storage `Folder` to a new `location` in the\\nDataModel.","params":[{"name":"location","desc":"New parent. Defaults to `workspace`.","lua_type":"Instance?"}],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolInstance"}],"function_type":"method","source":{"line":311,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"SetInsertFunction","desc":"Replaces the pool\'s `insertFunction`.  When `applyFunction` is `true` the\\nnew callback is immediately called on every instance currently in the pool.","params":[{"name":"insertFunction","desc":"New callback, or `nil` to clear.","lua_type":"((PVInstance) -> ())?"},{"name":"applyFunction","desc":"When `true`, applies the callback to all existing pooled instances.","lua_type":"boolean?"}],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolInstance"}],"function_type":"method","source":{"line":333,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"MakeGlobal","desc":"Registers the pool in the shared `GenericPoolInstance.globalPools` registry\\nunder `globalName`.  Any previous registration under a different name is\\ncleared first.","params":[{"name":"globalName","desc":"Key used to look up this pool globally.","lua_type":"string"}],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolInstance"}],"function_type":"method","source":{"line":359,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"MakeLocal","desc":"Removes the pool from the global registry.  Has no effect if the pool was\\nnever registered globally.","params":[],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolInstance"}],"function_type":"method","source":{"line":378,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"ContainsObject","desc":"Returns whether `object` is currently held inside this pool.","params":[{"name":"object","desc":"The instance to search for.","lua_type":"PVInstance"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"method","source":{"line":394,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"LoadObjects","desc":"Pre-fills the pool by cloning `objectCount` additional instances from the\\ntemplate (capped by `maxSize` when set).","params":[{"name":"objectCount","desc":"Number of new clones to add.","lua_type":"number"}],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolInstance"}],"function_type":"method","source":{"line":406,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"InsertObject","desc":"Returns a single externally-owned instance back into the pool.  The\\ninstance is teleported to the off-screen holding position and\\nre-parented to the internal folder.  No-ops if the pool is at capacity.","params":[{"name":"object","desc":"The instance to recycle.","lua_type":"PVInstance"}],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolInstance"}],"function_type":"method","source":{"line":436,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"InsertObjects","desc":"Bulk-recycles an array of externally-owned instances back into the pool.\\nExcess instances beyond `maxSize` are silently dropped.","params":[{"name":"objects","desc":"Array of instances to recycle.","lua_type":"{PVInstance}"}],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolInstance"}],"function_type":"method","source":{"line":462,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"ReturnObject","desc":"Peeks at the most-recently-added instance without removing it from the pool.","params":[],"returns":[{"desc":"The top-of-stack instance, or `nil` if the pool is empty.","lua_type":"PVInstance?"}],"function_type":"method","source":{"line":495,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"ReturnObjects","desc":"Returns up to `objectCount` instances from the top of the pool stack\\n**without** removing them.  Returns `nil` if the pool is empty.","params":[{"name":"objectCount","desc":"Maximum number of instances to peek at.","lua_type":"number"}],"returns":[{"desc":"Array of instances (newest-first), or `nil`.","lua_type":"{PVInstance}?"}],"function_type":"method","source":{"line":507,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"ReturnCustomObject","desc":"Peeks at the most-recently-added instance that satisfies `predicate`\\nwithout removing it from the pool.","params":[{"name":"predicate","desc":"Filter function.","lua_type":"(PVInstance) -> boolean"}],"returns":[{"desc":"Matching instance, or `nil`.","lua_type":"PVInstance?"}],"function_type":"method","source":{"line":530,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"ReturnCustomObjects","desc":"Peeks at all pooled instances that satisfy `predicate` without removing\\nthem.  Returns `nil` if none match.","params":[{"name":"predicate","desc":"Filter function.","lua_type":"(PVInstance) -> boolean"}],"returns":[{"desc":"Matching instances, or `nil`.","lua_type":"{PVInstance}?"}],"function_type":"method","source":{"line":552,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"RemoveObject","desc":"Permanently removes `object` from the pool and destroys it.","params":[{"name":"object","desc":"The instance to remove and destroy.","lua_type":"PVInstance"}],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolInstance"}],"function_type":"method","source":{"line":575,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"RetrieveObject","desc":"Removes and returns one instance from the pool.  If the pool is empty it\\nauto-expands by `expandSize` clones first.  When `cframe` is provided the\\ninstance is scheduled for a batched `BulkMoveTo` on the next `PreRender`.","params":[{"name":"cframe","desc":"Optional target position for the retrieved instance.","lua_type":"CFrame?"}],"returns":[{"desc":"The retrieved instance (never `nil`; expands automatically).","lua_type":"PVInstance"}],"function_type":"method","source":{"line":596,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"RetrieveObjects","desc":"Removes and returns `objectCount` instances from the pool.  Auto-expands\\nif there are not enough idle instances.","params":[{"name":"objectCount","desc":"Number of instances to retrieve.","lua_type":"number"}],"returns":[{"desc":"Array of retrieved instances.","lua_type":"{PVInstance}"}],"function_type":"method","source":{"line":618,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"RetrieveCustomObject","desc":"Removes and returns the first pooled instance that satisfies `predicate`,\\nsearching from newest to oldest.  If `cframe` is provided the instance is\\nscheduled for a `BulkMoveTo`.  Returns `nil` if nothing matches.","params":[{"name":"predicate","desc":"Filter function.","lua_type":"(PVInstance) -> boolean"},{"name":"cframe","desc":"Optional target position.","lua_type":"CFrame?"}],"returns":[{"desc":"The matching instance, or `nil`.","lua_type":"PVInstance?"}],"function_type":"method","source":{"line":659,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"RetrieveCustomObjects","desc":"Removes and returns all pooled instances that satisfy `predicate`.\\nReturns `nil` if nothing matches.","params":[{"name":"predicate","desc":"Filter function.","lua_type":"(PVInstance) -> boolean"}],"returns":[{"desc":"Matching instances, or `nil`.","lua_type":"{PVInstance}?"}],"function_type":"method","source":{"line":685,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"Clone","desc":"Creates a new `GenericPoolInstance` pool with the same configuration and\\na deep copy of all currently pooled instances.","params":[],"returns":[{"desc":"The cloned pool.","lua_type":"GenericPoolInstance"}],"function_type":"method","source":{"line":708,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"Clear","desc":"Destroys all instances currently held in the pool and empties the pool\\narray.  The pool itself remains usable; it will auto-expand on the next\\n`RetrieveObject` call.","params":[],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolInstance"}],"function_type":"method","source":{"line":731,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}},{"name":"Destroy","desc":"Destroys all pooled instances, removes the internal storage folder, and\\nde-registers the pool from the global registry.  The pool table is wiped\\nand the metatable cleared; the reference should be discarded afterwards.","params":[],"returns":[],"function_type":"method","source":{"line":747,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}}],"properties":[],"types":[],"name":"GenericPoolInstance","desc":"A reusable Roblox `PVInstance` (Part or Model) object pool that manages\\ncreation, retrieval, and recycling of instances.  Instances are stored in\\na hidden `Folder` at `math.huge` when idle, then teleported to their\\nrequested `CFrame` via a batched `BulkMoveTo` call on the next\\n`PreRender` step.\\n\\nPools can be registered in a shared registry via `MakeGlobal` so that\\nmultiple scripts can access the same pool by name.\\n\\n```lua\\nlocal GenericPoolInstance = require(path.to.GenericPoolInstance)\\n\\nlocal pool = GenericPoolInstance.new(workspace.MyTemplate, 20, 100, 10)\\nlocal part = pool:RetrieveObject(CFrame.new(0, 5, 0))\\n-- ... use part ...\\npool:InsertObject(part)\\n```","source":{"line":25,"path":"src/ReplicatedStorage/SharedModules/GenericPoolInstance.luau"}}')}}]);